CREATE TABLE source_cells(sheet_id INTEGER NOT NULL REFERENCES source_sheets(sheet_id),source_row INTEGER NOT NULL CHECK(source_row>0),source_column INTEGER NOT NULL CHECK(source_column>0),cell_json TEXT NOT NULL,PRIMARY KEY(sheet_id,source_row,source_column));
CREATE TABLE source_sheets(sheet_id INTEGER PRIMARY KEY,title TEXT NOT NULL,row_count INTEGER NOT NULL,column_count INTEGER NOT NULL);
CREATE TABLE "units" (source_row INTEGER PRIMARY KEY CHECK(source_row>1),"unit_name","type","uniqueness","manufacturer","set_wave","valkyrie","species","class","personality","size","height","figures","cost","life","move","range","attack","defense","ability_name_1","ability_description_1","ability_name_2","ability_description_2","ability_name_3","ability_description_3","ability_name_4","ability_description_4","purchase_link_all_things_heroscape","purchase_link_renegade_game_studios_painted","purchase_link_renegade_game_studios_unpainted","more_information","column_31");
